using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsInspectorOperations:RefCounted
{
    private readonly PhysicsSettingsOperations _settings=new();private readonly ActorPropertyOperations _properties=new();private readonly ActorDataOperations _data=new();
    private static Control Host(RefCounted owner)=>owner.Get("inspector").As<Control>();private static Resource Actor(RefCounted owner)=>owner.Get("actor").As<Resource>();private static RefCounted Model(RefCounted owner)=>owner.Get("model").As<RefCounted>();private static VBoxContainer Panel(RefCounted owner)=>owner.Get("panel").As<VBoxContainer>();private static Settings Initial(RefCounted owner)=>owner.Get("settings").AsGodotDictionary();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private Settings Sample(RefCounted owner){var actor=Actor(owner);double time=actor.Get("animation_time").AsDouble();return _settings.sample(actor,double.IsNaN(time)?0:time);}
    private static SpinBox Number()=>new DragNumber();private static void Update(RefCounted owner,Callable callback)=>Host(owner).Get("_updaters").AsGodotArray().Add(callback);
    public void build(Control host,Resource actor,VBoxContainer panel){var owner=GD.Load<GDScript>("res://scripts/actors/physics/physics_inspector.gd").New().As<RefCounted>();owner.Set("inspector",host);owner.Set("actor",actor);owner.Set("model",host.Get("model"));owner.Set("panel",panel);owner.Set("settings",Sample(owner));owner.Call("_build");}
    public void change(RefCounted owner,string key,Variant value,bool rebuild){if(key=="mode"&&value.AsInt32()==3){var editor=owner.Call("_editor").AsGodotObject();if(editor!=null){editor.Get("physics").AsGodotObject().Call("freeze",Model(owner),Actor(owner));Host(owner).Call("_queue_rebuild_selected");return;}}_settings.edit(Model(owner),Actor(owner),key,value);if(rebuild)Host(owner).Call("_queue_rebuild_selected");}
    public void heading(RefCounted owner,string text)=>Host(owner).Call("_add_label",Panel(owner),text);
    public HBoxContainer property(RefCounted owner,string key,string title,VBoxContainer parent,bool keyed){var row=new HBoxContainer();parent.AddChild(row);string labelText=key switch{"activation"=>"Activation (s)","influence"=>"Influence","gravity"=>"Gravity","damping"=>"Damping",_=>title};row.AddChild(new Label{Text=labelText,TooltipText=title,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});if(keyed){var property=_properties.create(new StringName("physics_"+key),title,Get(Initial(owner),key),true);property.Get("options").AsGodotDictionary()["group"]="Physics";Host(owner).Call("_add_keyframe_button",row,Actor(owner),property,new[]{"physics",key},Get(Initial(owner),key));}return row;}
    public void check(RefCounted owner,string key,string title,VBoxContainer parent,bool rebuild){var row=property(owner,key,title,parent,true);var input=new CheckButton{Name="Physics_"+key,ButtonPressed=Initial(owner)[key].AsBool()};row.AddChild(input);input.Toggled+=value=>change(owner,key,value,rebuild);Update(owner,Callable.From(()=>input.SetPressedNoSignal(Sample(owner)[key].AsBool())));}
    public void choice(RefCounted owner,string key,string title,GArray choices,VBoxContainer parent){property(owner,key,title,parent,false);var input=new OptionButton{Name="Physics_"+key,FitToLongestItem=false};parent.AddChild(input);foreach(var value in choices)input.AddItem(value.AsString());var actor=Actor(owner);var settings=Initial(owner);string type=actor.Get("type_id").AsString();if(key=="mode"&&(type is "fluid" or "powder"||settings["type"].AsInt32()==9)){foreach(int index in new[]{0,2})input.SetItemDisabled(index,true);input.GetPopup().SetItemTooltip(0,type=="powder"?"Use Freeze to hold the grain state, or turn off Simulate grains for source preview.":"Use Freeze to hold the reconstructed liquid surface.");input.GetPopup().SetItemTooltip(2,type=="powder"?"Spring-guided motion is not a granular control mode.":"Spring-guided motion is not a liquid control mode.");}var bake=settings["bake"].AsGodotDictionary();var cache=Get(bake,"cache").AsGodotObject() as Resource;if(key=="mode"&&Get(bake,"frames",new GArray()).AsGodotArray().Count==0&&!ActorDataOperations.ScriptIs(cache,"res://scripts/actors/physics/destruction/physics_bake_cache.gd")){input.SetItemDisabled(4,true);input.GetPopup().SetItemTooltip(4,"Use Bake… to create baked physics first.");}input.Select(Math.Min(Math.Max(settings[key].AsInt32(),0),choices.Count-1));input.ItemSelected+=value=>change(owner,key,value,true);}
    public void number(RefCounted owner,string key,string title,VBoxContainer parent,double low,double high,double step,bool keyed){property(owner,key,title,parent,keyed);var input=Number();input.Name="Physics_"+key;input.MinValue=low;input.MaxValue=high;input.Step=step;input.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;input.SetValueNoSignal(Initial(owner)[key].AsDouble());parent.AddChild(input);bind_number(owner,input,key,-1);}
    private sealed class Gesture{internal bool Active;internal Settings Before=new();internal Variant Tracks;}
    public void bind_number(RefCounted owner,SpinBox input,string key,int axis)
    {
        var gesture=new Gesture();var actor=Actor(owner);var model=Model(owner);var path=new[]{"physics",key};Variant Convert(double value){if(axis<0)return input.Step>=1?Variant.From((long)value):Variant.From(value);var next=Sample(owner)[key].AsVector3();next[axis]=(float)value;return next;}void Restore(){actor.Get("values").AsGodotDictionary()[new StringName("physics")]=gesture.Before.Duplicate(true);actor.Get("animation_previews").AsGodotDictionary().Clear();model.Call("restore_animation",actor,gesture.Tracks);gesture.Active=false;}
        input.Connect("interaction_started",Callable.From(()=>{gesture.Before=_settings.authored(actor);gesture.Tracks=model.Call("animation_snapshot",actor);gesture.Active=true;}));input.Connect("preview_changed",Callable.From<double>(value=>{var normalized=Convert(value);if(_data.animation_track(actor,path)!=null)model.Call("preview_animation_value",actor,path,normalized);else{var next=_settings.authored(actor);next[key]=normalized;actor.Get("values").AsGodotDictionary()[new StringName("physics")]=next;model.EmitSignal("changed");}}));input.Connect("drag_committed",Callable.From<double>(value=>{if(gesture.Active)Restore();change(owner,key,Convert(value),false);}));input.Connect("drag_cancelled",Callable.From(()=>{if(gesture.Active)Restore();}));input.ValueChanged+=value=>change(owner,key,Convert(value),false);input.Connect("interaction_ended",Callable.From(()=>{if(gesture.Active&&Mathf.IsEqualApprox(input.Value,input.Get("_origin").AsDouble()))Restore();}));Update(owner,Callable.From(()=>{if(gesture.Active)return;var value=Sample(owner)[key];input.SetValueNoSignal(axis<0?value.AsDouble():value.AsVector3()[axis]);}));
    }
    public void vector(RefCounted owner,string key,string title,VBoxContainer parent){property(owner,key,title,parent,true);var values=Initial(owner)[key].AsVector3();for(int axis=0;axis<3;axis++){var row=new HBoxContainer();parent.AddChild(row);row.AddChild(new Label{Text=new[]{"X","Y","Z"}[axis]});var input=Number();input.Name="Physics_"+key+"_"+axis;input.AllowGreater=true;input.AllowLesser=true;input.Step=.01;input.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;input.SetValueNoSignal(values[axis]);row.AddChild(input);bind_number(owner,input,key,axis);}}
    public VBoxContainer fold(RefCounted owner,string title){var host=Host(owner);var actor=Actor(owner);var state=host.Get("ui_state").AsGodotObject();var categories=Get(state.Call("_actor_state",actor.Get("id")).AsGodotDictionary(),"categories",new Settings()).AsGodotDictionary();if(!categories.ContainsKey("Physics:"+title))state.Call("set_category_expanded",actor.Get("id"),"Physics:"+title,false);return host.Call("_stateful_category",title,actor.Get("id"),Panel(owner),"Physics").As<VBoxContainer>();}
}
